import 'dart:convert';
import 'package:flutter/foundation.dart';
import 'package:flutter/painting.dart';
import 'package:http/http.dart' as http;
import '../../ball_management/domain/custom_ball.dart';
import '../../replay_export/domain/replay_link.dart';
import '../domain/ball_pack.dart';

/// Loads the built-in packs (`web/packs/packs.json` plus images), hosted with
/// the web app on GitHub Pages. Generated by `tool/build_packs.mjs`.
class BallPackRepository {
  final Uri baseUri;
  final Future<String> Function(Uri url) _fetch;
  Future<List<BallPack>>? _packs;

  BallPackRepository({Uri? baseUri, Future<String> Function(Uri url)? fetch})
      : baseUri = baseUri ?? defaultBaseUri,
        _fetch = fetch ?? _httpFetch;

  /// The running site on web (works for local builds too); the hosted site
  /// from the Android app.
  static Uri get defaultBaseUri =>
      (kIsWeb ? Uri.base.replace(query: '', fragment: '') : Uri.parse(kWebAppUrl)).resolve('packs/');

  /// All packs, loaded once. A failed load can be retried by calling again.
  Future<List<BallPack>> load() {
    final pending = _packs ??= _load();
    pending.catchError((Object _) {
      _packs = null;
      return <BallPack>[];
    });
    return pending;
  }

  Future<List<BallPack>> _load() async {
    final json = jsonDecode(await _fetch(baseUri.resolve('packs.json'))) as Map<String, dynamic>;
    return [
      for (final g in json['groups'] as List)
        BallPack(
          id: g['id'] as String,
          name: g['name'] as String,
          balls: [
            for (final b in g['balls'] as List)
              _ball(g['id'] as String, g['style'] == 'flag' ? BallImageStyle.cover : BallImageStyle.logo, b),
          ],
        ),
    ];
  }

  CustomBall _ball(String packId, BallImageStyle style, Map<String, dynamic> b) {
    final color = _parseHex(b['color'] as String);
    return CustomBall(
      id: BallPack.ballId(packId, b['id'] as String),
      name: b['name'] as String,
      imageUrl: baseUri.resolve(b['image'] as String).toString(),
      imageStyle: style,
      primaryColor: color,
      glowColor: Color.lerp(color, const Color(0xFFFFFFFF), 0.35)!,
    );
  }

  static Color _parseHex(String hex) => Color(0xFF000000 | int.parse(hex.replaceFirst('#', ''), radix: 16));

  static Future<String> _httpFetch(Uri url) async {
    final res = await http.get(url);
    if (res.statusCode != 200) throw Exception('HTTP ${res.statusCode} for $url');
    return utf8.decode(res.bodyBytes);
  }
}
